let state=C.blank(),draft=null,history=[],owner=false,panel='control',selectedMatch=null,selectedTeam=0,teamIndex=0,revision=0,stream=null,camera=null,previewMode=false,loaded=false,authGeneration=0,selectedCameraId='',cameraRequest=0,screenRequest=0,gameInputMode='screen',gameVideoId='',gameAudioId='',selectedMicId='',pendingSetup=null;
const root=document.createElement('section');root.id='live-broadcast';root.className='section';root.innerHTML='<div class="lb-toolbar"><h2>LIVE BROADCAST</h2><span class="lb-pill" id="lb-source">NOT CONNECTED</span><button id="lb-refresh">Refresh broadcast</button><button id="lb-owner-open" hidden>OWNER DASHBOARD</button><button id="lb-demo">Preview sample layout</button><button id="lb-watch">Watch live video</button><button id="lb-return-layout" hidden>Return to scoreboard</button></div><div class="lb-panel lb-setup-shortcuts"><h3>OWNER SETUP / सञ्चालकका लागि</h3><div class="lb-toolbar"><button id="lb-setup-login">OWNER LOGIN / SETUP</button><button id="lb-setup-teams">१ · Registered Team छानेर LIVE मा राख्नुहोस्</button><button id="lb-setup-channels">२ · YouTube / TikTok Channel Links</button></div><p class="lb-note">Owner login आवश्यक छ। Registered team को logo, ४ photo र PUBG names छानेर ल्याउनुहोस्।</p></div><div id="lb-channel-links" class="lb-toolbar"></div><p class="lb-note">Public broadcast · owner supplied data. Automatic gameplay telemetry is not connected. Live video requires an owner-started studio.</p><div id="lb-watch-stage" hidden><video id="lb-watch-video" autoplay playsinline controls muted></video><button id="lb-enable-sound">Enable broadcast sound</button></div><div class="lb-shell" id="lb-board"></div><details class="lb-panel"><summary>CO-HOST STUDIO · invitation required</summary><div class="lb-form"><label>Studio ID<input id="lb-join-id" autocomplete="off"></label><label>Invitation password<input id="lb-join-password" type="password" autocomplete="off"></label></div><div class="lb-toolbar"><label>Camera device<select id="lb-cohost-camera-select"><option value="">Default camera</option></select></label><button id="lb-cohost-camera-refresh">Refresh USB / built-in cameras</button><button id="lb-cohost-camera-enable">Enable / switch camera</button><label>My microphone<select id="lb-cohost-mic-select"><option value="">Default microphone</option></select></label><button id="lb-join-cohost">Join as co-host</button><button id="lb-leave-studio">Leave studio / stop camera & mic</button><button id="lb-resume-audio">Enable host sound</button><button id="lb-toggle-studio-mic">Mute / unmute my microphone</button><button id="lb-toggle-studio-camera">Hide / show my camera</button></div><p class="lb-note">Use headphones. You receive game audio and the other host; your own microphone is excluded from your return feed.</p></details><div class="lb-status" id="lb-status" role="status"></div><div class="lb-owner" id="lb-owner" hidden></div>';
