async function studioApi(action,body={}){if(typeof SUPABASE_URL==='undefined')throw Error('Studio service is not configured');const {data:{session}}=await sb.auth.getSession();const res=await fetch(SUPABASE_URL+'/functions/v1/rock-broadcast-studio',{method:'POST',headers:{'Content-Type':'application/json',apikey:SUPABASE_KEY,...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,...body})});let result;try{result=await res.json();}catch(e){throw Error('Studio service unavailable');}if(!res.ok)throw Error(result.error||'Studio request failed');return result;}
