function card(t,i){return `<article class="lb-card"><div class="lb-teamhead"><span class="lb-slot">A${i+1}</span>${t.logo?img(t.logo,'Team logo'):''}<strong>${E(t.name)}</strong><span>K ${t.players.reduce((n,p)=>n+p.kills,0)}</span></div><div class="lb-players">${t.players.map(p=>`<div class="lb-player ${p.status}">${img(p.photo,p.name+' portrait')}<b title="${E(p.name)}">${E(p.name)}</b><div class="lb-health"><i style="width:${p.health}%;background:${p.health<30?'#ec263e':p.health<70?'#dbb700':'#1ed82b'}"></i><span>${p.status==='out'?'OUT':p.status==='knock'?'KNOCK':p.health+'%'} · K${p.kills}</span></div></div>`).join('')}</div></article>`;}
function table(teams,select=false,limit=16){return `<div class="lb-table-wrap"><table class="lb-table"><thead><tr><th>#</th><th>TEAM</th><th>PLACE</th><th>KILLS</th><th>PLACE PTS</th><th>TOTAL</th></tr></thead><tbody>${C.ranking(teams).slice(0,limit).map((t,i)=>`<tr><td>${i+1}</td><td>${select?`<button data-result-team="${E(t.id)}">${E(t.name)}</button>`:E(t.short||t.name)}</td><td>${t.placement??'—'}</td><td>${t.kills}</td><td>${t.placementPoints}</td><td>${t.total}</td></tr>`).join('')}</tbody></table></div>`;}
